/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailLoyaltyCardReplacementCard extends UPSPricingAttributeRetailLoyaltyCard implements UPSIPricingAttribute
{
}

