public str getName()
{
    return fieldPName(RetailLoyaltyCard, ReplacementCard);
}

public Set getAllowedValues()
{
    RetailLoyaltyCard   retailLoyaltyCard;
    var                 ret = new Set(Types::Int64);

    while select RecId from retailLoyaltyCard
    {
        ret.add(retailLoyaltyCard.RecId);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailLoyaltyCard, ReplacementCard));
    qbr.value(queryValue(_value));
}
